#!/usr/bin/env python3
"""Инструменты, которые считались однописьменными, пишут как все остальные.

«Однописьменный» — это ДОПУЩЕНИЕ, а не свойство кода. Восемь инструментов
собирали временного соседа руками именно потому, что про каждый было известно:
его запускают по одному. Про три из восьми это неверно уже сегодня:

  · сторож по замыслу живёт РЯДОМ с другими процессами — он для того и заведён;
  · панель хода переписывается на каждой записи состояния, и её же в этот
    момент пересобирает соседний вызов;
  · журнал находок пишется и из подагента тоже, а подтверждение находки —
    это чтение счётчика, прибавление единицы и запись обратно.

Цена ошибки в допущении несоразмерна: общий временный путь и отсутствие замка
теряют чужую правку МОЛЧА, с кодом возврата 0 у обоих процессов.

Что здесь заперто, по двум свойствам общего модуля записи:

  · права не расширяются — существовавший файл сохраняет режим, новый
    создаётся приватным, а не по umask;
  · одновременная запись не теряется молча — пересборка страницы переживает
    параллельную запись снимка, а два подтверждения одной находки дают два
    прибавления счётчика, а не одно.

Одновременность настоящая: два потока операционной системы, сведённые
барьером, и разрыв между чтением и записью, открытый нарочно. Без разрыва
исход зависел бы от планировщика — то есть один и тот же код отвечал бы
то так, то иначе.
"""
from __future__ import annotations

import argparse
import contextlib
import importlib.util
import io
import json
import os
import stat
import sys
import tempfile
import threading
import time
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
ИНСТРУМЕНТЫ = РЕПО / "plugins" / "superstack" / "tools"
ХУКИ = РЕПО / "plugins" / "superstack" / "hooks"

# Каталог инструментов в пути: общий модуль записи соседи импортируют по имени,
# и без этого ни один из них не загрузится вовсе.
if str(ИНСТРУМЕНТЫ) not in sys.path:
    sys.path.insert(0, str(ИНСТРУМЕНТЫ))


def _загрузить(имя: str, файл: Path):
    спек = importlib.util.spec_from_file_location(имя, файл)
    мод = importlib.util.module_from_spec(спек)
    sys.modules[имя] = мод
    спек.loader.exec_module(мод)
    return мод


сторож = _загрузить("ss_watchdog_one_writer", ИНСТРУМЕНТЫ / "watchdog.py")
панель = _загрузить("ss_live_" "panel_on" "e_writer", ИНСТРУМЕНТЫ / "live_panel.py")
находки = _загрузить("ss_learn_one_writer", ИНСТРУМЕНТЫ / "learn.py")
ход = _загрузить("ss_progress_one_writer", ИНСТРУМЕНТЫ / "progress.py")
# Девятый писатель: в находку он не попал вовсе, потому что искали по перечню
# имён инструментов, а он хук. Копия разговора — самое приватное, что вообще
# кладётся на диск этим продуктом.
сжатие = _загрузить("ss_preco" "mpact_on" "e_writer", ХУКИ / "precompact.py")

#: Почему часть проверок не имеет смысла вне POSIX. Пропуск НАЗЫВАЕТСЯ: молча
#: пропущенная проверка читается как пройденная, а это разные утверждения.
ПОЧЕМУ_POSIX = ("права файла — понятие POSIX: на Windows доступ выражается "
                "списком прав. Пропуск назван вслух, чтобы «не проверяли» не "
                "читалось как «прошло»")
ТОЛЬКО_POSIX = unittest.skipUnless(os.name == "posix", ПОЧЕМУ_POSIX)

#: Разрыв между чтением и записью. Столько времени состояние уже прочитано, но
#: ещё не записано, — ровно окно, в которое влезает второй процесс.
ОКНО = 0.2


class Каталог(unittest.TestCase):
    """Всё пишется в свой временный каталог и исчезает с тестом."""

    def setUp(self):
        врем = tempfile.TemporaryDirectory()
        self.addCleanup(врем.cleanup)
        self.дом = Path(врем.name)
        # Тот самый обычный umask, при котором 0600 превращался в 0644.
        прежний = os.umask(0o022)
        self.addCleanup(os.umask, прежний)

    def режим(self, файл: Path) -> str:
        return oct(stat.S_IMODE(файл.stat().st_mode))


class ПраваНеРастут(Каталог):
    """Замена файла режима не наследует: 0600 превращался в 0644."""

    @ТОЛЬКО_POSIX
    def test_снимок_сторожа_рождается_приватным(self):
        файл = self.дом / "снимок.json"
        сторож._атомарная_запись(файл, json.dumps({"код": 0}))
        self.assertEqual(self.режим(файл), oct(0o600),
                         "состояние сторожа создано по umask — то есть "
                         "читаемым другим локальным пользователям машины")

    @ТОЛЬКО_POSIX
    def test_снимок_сторожа_сохраняет_режим_существующего(self):
        """Обратная половина того же правила: режим СОХРАНЯЕТСЯ, а не
        назначается заново. Всегда запирать чужой файл — тоже менять решение
        человека, просто в другую сторону."""
        файл = self.дом / "снимок.json"
        файл.write_text("{}", encoding="utf-8")
        os.chmod(файл, 0o644)
        сторож._атомарная_запись(файл, json.dumps({"код": 0}))
        self.assertEqual(self.режим(файл), oct(0o644),
                         "запись переназначила режим существовавшего файла")

    @ТОЛЬКО_POSIX
    def test_запись_находки_приватна(self):
        файл = self.дом / "находка.json"
        находки.write_atomic(файл, {"id": "abc", "title": "находка"})
        self.assertEqual(self.режим(файл), oct(0o600),
                         "журнал находок читаем другим локальным "
                         "пользователям: в нём лежат куски работы человека")

    @ТОЛЬКО_POSIX
    def test_запись_находки_сохраняет_режим_существующего(self):
        файл = self.дом / "находка.json"
        файл.write_text("{}", encoding="utf-8")
        os.chmod(файл, 0o600)
        находки.write_atomic(файл, {"id": "abc", "title": "находка"})
        self.assertEqual(self.режим(файл), oct(0o600),
                         "запись расширила права журнала находок")

    @ТОЛЬКО_POSIX
    def test_страница_панели_рождается_приватной(self):
        прогон = self.дом / ".superstack"
        прогон.mkdir()
        (прогон / "state.json").write_text(
            json.dumps(ход.EMPTY, ensure_ascii=False), encoding="utf-8")
        стр = панель.write_panel(прогон)
        self.assertEqual(self.режим(стр), oct(0o600),
                         "страница хода создана по umask")

    def test_временных_файлов_рядом_не_остаётся(self):
        файл = self.дом / "снимок.json"
        сторож._атомарная_запись(файл, "{}")
        мусор = sorted(p.name for p in self.дом.iterdir()
                       if p.name.endswith(".tmp"))
        self.assertEqual(мусор, [], "временный сосед остался лежать рядом")


class КопияРазговораНеЧитаемаСоседям(Каталог):
    """Транскрипт копировался прямым `copyfile` и получал права по umask.

    То есть весь разговор человека — с путями, кусками кода и всем, что он
    успел продиктовать, — становился читаемым любому, у кого есть учётная
    запись на этой машине. Заметить это было неоткуда: читать копию никто
    не пробовал.
    """

    def _транскрипт(self) -> Path:
        src = self.дом / "разговор.jsonl"
        src.write_text('{"role":"user","content":"привет"}\n', encoding="utf-8")
        return src

    @ТОЛЬКО_POSIX
    def test_новая_копия_приватна(self):
        куда = self.дом / "снимки" / "сессия.jsonl"
        self.assertEqual(сжатие.сохранить(str(self._транскрипт()), куда), "saved")
        self.assertEqual(self.режим(куда), oct(0o600),
                         "копия разговора создана по umask — читаема любому "
                         "локальному пользователю машины")

    @ТОЛЬКО_POSIX
    def test_копия_сохраняет_режим_существующей(self):
        куда = self.дом / "сессия.jsonl"
        куда.write_text("прежняя копия\n", encoding="utf-8")
        os.chmod(куда, 0o644)
        self.assertEqual(сжатие.сохранить(str(self._транскрипт()), куда), "saved")
        self.assertEqual(self.режим(куда), oct(0o644),
                         "запись переназначила режим существовавшей копии")

    def test_копия_совпадает_с_исходником_байт_в_байт(self):
        """Обратный контроль: перевод на общий модуль не имеет права менять
        то, ради чего копия существует."""
        src = self._транскрипт()
        куда = self.дом / "сессия.jsonl"
        сжатие.сохранить(str(src), куда)
        self.assertEqual(куда.read_bytes(), src.read_bytes())
        мусор = sorted(p.name for p in self.дом.iterdir()
                       if p.name.endswith(".tmp"))
        self.assertEqual(мусор, [], "временный сосед остался лежать рядом")


class ПересборкаСтраницыПереживаетЗаписьСнимка(Каталог):
    """Панель читают и пишут два разных вызова, и оба пишут её ЦЕЛИКОМ.

    Вписывание снимка читает страницу с диска, меняет в ней один кусок и
    кладёт обратно. Пересборка в это же время кладёт свежую разметку. Без
    замка на весь цикл вписывание записывает поверх свежей страницы ту,
    которую прочитало ДО пересборки, — и панель, начатая прежней версией,
    остаётся на прежней версии, выглядя свежей.
    """

    МЕТКА = "<!--СБОРКА ПРОШЛОЙ ВЕРСИИ-->"

    def setUp(self):
        super().setUp()
        self.прогон = self.дом / ".superstack"
        self.прогон.mkdir()
        (self.прогон / "state.json").write_text(
            json.dumps(ход.EMPTY, ensure_ascii=False), encoding="utf-8")
        self.стр = панель.write_panel(self.прогон)
        # Страница «прошлой версии»: та же разметка с меткой, по которой видно,
        # что на диске лежит именно она.
        self.стр.write_text(self.МЕТКА + "\n" + self.стр.read_text("utf-8"),
                            encoding="utf-8")

    def разорвать_цикл(self) -> None:
        """Задержать ЗАПИСЬ снимка, оставив чтение страницы на месте."""
        настоящий = панель._with_snapshot

        def медленно(html, state):
            if threading.current_thread().name == "снимок":
                time.sleep(ОКНО)
            return настоящий(html, state)

        панель._with_snapshot = медленно
        self.addCleanup(setattr, панель, "_with_snapshot", настоящий)

    def test_пересборка_не_теряется_под_записью_снимка(self):
        self.разорвать_цикл()
        барьер = threading.Barrier(2, timeout=30)
        беды = []

        def снимок():
            try:
                барьер.wait()
                панель.embed_state(self.прогон, dict(ход.EMPTY))
            except BaseException as e:                       # noqa: BLE001
                беды.append(f"снимок: {e!r}")

        def пересборка():
            try:
                барьер.wait()
                панель.write_panel(self.прогон)
            except BaseException as e:                       # noqa: BLE001
                беды.append(f"пересборка: {e!r}")

        потоки = [threading.Thread(target=снимок, name="снимок"),
                  threading.Thread(target=пересборка, name="пересборка")]
        for п in потоки:
            п.start()
        for п in потоки:
            п.join(timeout=60)

        self.assertEqual([п.name for п in потоки if п.is_alive()], [],
                         "поток не вернулся — запись страницы зависла")
        self.assertEqual(беды, [], "запись страницы упала")
        стало = self.стр.read_text("utf-8")
        self.assertNotIn(
            self.МЕТКА, стало,
            "снимок записал поверх пересобранной страницы ту, что прочитал "
            "до неё: пересборка пропала молча, оба вызова вернулись успешно")
        self.assertIn(панель.SNAPSHOT_BEGIN, стало,
                      "страница осталась без границ снимка")


class ДваПодтвержденияОднойНаходки(Каталог):
    """Повторная встреча находки — это чтение счётчика, +1 и запись обратно.

    Два подагента, наткнувшиеся на один и тот же урок, читают одно и то же
    число и записывают одно и то же «плюс один»: без замка на весь цикл
    подтверждений становится не три, а два, и потерю не видно ниоткуда —
    оба вызова печатают успех.
    """

    ЗАГОЛОВОК = "запись через общий модуль не теряет чужую правку"

    def setUp(self):
        super().setUp()
        было = находки.LOCAL
        self.addCleanup(setattr, находки, "LOCAL", было)
        находки.LOCAL = self.дом / "learned"

    def _просьба(self) -> argparse.Namespace:
        return argparse.Namespace(
            title=self.ЗАГОЛОВОК, check="прогон набора",
            failure="правка пропала молча", deadend="атомарной замены мало",
            source=None, tags=None, notes=None, scope="local", kind="fact",
            paths=None)

    def разорвать_цикл(self) -> None:
        настоящая = находки.write_atomic

        def медленно(path, data):
            time.sleep(ОКНО)
            настоящая(path, data)

        находки.write_atomic = медленно
        self.addCleanup(setattr, находки, "write_atomic", настоящая)

    def запись(self) -> dict:
        файлы = sorted(находки.LOCAL.glob("*.json"))
        self.assertEqual(len(файлы), 1, файлы)
        return json.loads(файлы[0].read_text("utf-8"))

    def test_второе_подтверждение_не_затирает_первое(self):
        глухо = io.StringIO()
        with contextlib.redirect_stdout(глухо):
            self.assertEqual(находки.cmd_add(self._просьба()), 0, глухо.getvalue())
            self.assertEqual(self.запись()["confirmations"], 1)

            self.разорвать_цикл()
            барьер = threading.Barrier(2, timeout=30)
            беды = []

            def подтверждает():
                try:
                    барьер.wait()
                    находки.cmd_add(self._просьба())
                except BaseException as e:                   # noqa: BLE001
                    беды.append(repr(e))

            потоки = [threading.Thread(target=подтверждает) for _ in range(2)]
            for п in потоки:
                п.start()
            for п in потоки:
                п.join(timeout=60)

        self.assertEqual([п.name for п in потоки if п.is_alive()], [],
                         "поток не вернулся — запись находки зависла")
        self.assertEqual(беды, [], "запись находки упала")
        self.assertEqual(
            self.запись()["confirmations"], 3,
            "одно из двух подтверждений пропало: оба процесса прочитали одно "
            "число и записали одно и то же «плюс один», и оба отчитались "
            "успехом — ровно та молчаливая потеря, ради которой замок")


if __name__ == "__main__":
    unittest.main()
